from _h import *
DAY = 16

def L(t, ex): return {"t": t, "explain": ex}
def F(id, q, ans, explain): return fill(id, q, ans, explain)
def P(x): return dict(x, plainKeys=["opts"])
def C(id, q, opts, ans, explain): return P(choose(id, q, opts, ans, explain))
def M(id, q, opts, ans, explain): return P(mcq(id, q, opts, ans, explain))
Q1 = "1．（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。（1点×10問）\n"
Q2 = "2．＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。（1点×5問）\n"
Q3 = "3．次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。（2点×5問）\n"

